css:
#dyn-mosaic-theme[data-theme="mosaic-slant-rows"]{
  overflow:hidden;
  background:var(--background,#141414);
  --sr-texture:none;
  container-type:size;
}
#dyn-mosaic-theme[data-theme="mosaic-slant-rows"] .sr-chrome{
  position:absolute;z-index:6;width:min(11.5%,132px);aspect-ratio:1;pointer-events:none;
}
#dyn-mosaic-theme[data-theme="mosaic-slant-rows"] .sr-logo{top:3.4%;left:3.2%;}
#dyn-mosaic-theme[data-theme="mosaic-slant-rows"] .sr-qr{bottom:3.4%;right:3.2%;}
#dyn-mosaic-theme[data-theme="mosaic-slant-rows"] .sr-chrome img,
#dyn-mosaic-theme[data-theme="mosaic-slant-rows"] .sr-chrome canvas,
#dyn-mosaic-theme[data-theme="mosaic-slant-rows"] .sr-chrome svg{
  width:100%;height:100%;object-fit:contain;display:block;
}
#dyn-mosaic-theme.dyn-portrait[data-theme="mosaic-slant-rows"] .sr-chrome{
  width:min(18%,120px);
}
